const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню')});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));const booking=document.querySelector('#booking');document.querySelectorAll('[data-book],[data-service]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#service').value=b.dataset.service||'Нужна консультация';booking.showModal()}));document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});document.querySelector('#request-form').addEventListener('submit',e=>{e.preventDefault();const car=document.querySelector('#car').value.trim();if(!car){document.querySelector('#car').focus();return}const text='Здравствуйте! Интересует '+document.querySelector('#service').value.toLowerCase()+'. Автомобиль: '+car+'. Подскажите стоимость и ближайшее время для записи.';window.open('https://t.me/mxautoby?text='+encodeURIComponent(text),'_blank','noopener,noreferrer')});const photo=document.querySelector('#photo');document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{photo.querySelector('img').src=b.dataset.photo;photo.querySelector('img').alt=b.dataset.title;photo.querySelector('h3').textContent=b.dataset.title;photo.showModal()}));document.querySelector('#replay').addEventListener('click',()=>{const old=document.querySelector('.intro'),fresh=old.cloneNode(true);old.replaceWith(fresh)});

// Mobile enhancements never depend on device motion permissions.
const mobileQuery=matchMedia('(max-width:650px)'),reducedQuery=matchMedia('(prefers-reduced-motion:reduce)');
const meter=document.createElement('div');meter.className='scroll-meter';meter.setAttribute('aria-hidden','true');document.body.append(meter);
let scrollFrame=0;
function updateScroll(){scrollFrame=0;const y=window.scrollY,range=document.documentElement.scrollHeight-innerHeight;meter.style.transform=`scaleX(${range>0?Math.min(1,Math.max(0,y/range)):0})`;document.querySelector('header').classList.toggle('scrolled',y>16);}
addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(updateScroll)},{passive:true});addEventListener('resize',updateScroll,{passive:true});updateScroll();
if('IntersectionObserver' in window){const reveal=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');reveal.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px 25px 0px'});document.querySelectorAll('.section-head,.service,.selection,.steps article,.faq details,.contact-grid').forEach(el=>{if(mobileQuery.matches&&!reducedQuery.matches){el.classList.add('reveal-ready');reveal.observe(el)}});reducedQuery.addEventListener('change',()=>{if(reducedQuery.matches)document.querySelectorAll('.reveal-ready').forEach(el=>el.classList.add('in-view'))})}
document.querySelectorAll('.btn,.service,.work,.other-services button,.mobile-dock button').forEach(el=>{el.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')el.classList.add('touch-pressed')},{passive:true});['pointerup','pointercancel','pointerleave','lostpointercapture'].forEach(type=>el.addEventListener(type,()=>el.classList.remove('touch-pressed'),{passive:true}))});
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Открыть меню')}
document.addEventListener('click',e=>{if(!nav.contains(e.target)&&!menu.contains(e.target))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
const dialogObserver=new MutationObserver(()=>{document.body.classList.toggle('modal-open',!!document.querySelector('dialog[open]'));if(document.querySelector('dialog[open]'))closeMenu()});document.querySelectorAll('dialog').forEach(d=>dialogObserver.observe(d,{attributes:true,attributeFilter:['open']}));
if(window.visualViewport){const dock=document.querySelector('.mobile-dock');const syncKeyboard=()=>dock.classList.toggle('keyboard-hidden',!!document.querySelector('dialog[open]')&&window.visualViewport.height<innerHeight*.8);window.visualViewport.addEventListener('resize',syncKeyboard,{passive:true})}

// A CSS-first intro cannot leave an invisible interaction blocker behind.
function finishIntro(el){if(el&&el.isConnected)el.remove();}
function armIntro(el){if(!el)return;el.addEventListener('animationend',e=>{if(e.target===el&&e.animationName==='introOut')finishIntro(el)});setTimeout(()=>finishIntro(el),2800);}
armIntro(document.querySelector('.intro'));
// Replay uses the same bounded animation even after the original overlay is removed.
const replayButton=document.querySelector('#replay');
const safeReplay=replayButton.cloneNode(true);replayButton.replaceWith(safeReplay);
safeReplay.addEventListener('click',()=>{document.querySelector('.intro')?.remove();const el=document.createElement('div');el.className='intro';el.setAttribute('aria-hidden','true');el.innerHTML='<div class="intro-brand">MX<span>auto</span></div><div class="headlights"><i></i><i></i></div><p>ДЕТЕЙЛИНГ-СТУДИЯ В МИНСКЕ</p>';document.body.append(el);armIntro(el)});
